#!/usr/bin/env node
// Builds a real, signed fixtures/dist/revocations.json from the keypair
// generated by gen-keys.mjs — same repo key that signs index.json (the repo
// operator revokes their own repo's listings). Run `node scripts/gen-keys.mjs`
// then `node scripts/build-index.mjs` first.
//
// Usage: node scripts/build-crl.mjs [version]
//   version defaults to 1 if omitted (bump it manually to publish a newer CRL).
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { buildCrl } from "../lib/crl.mjs";
import { keyId } from "../lib/keys.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const fixturesDir = join(here, "..", "fixtures");
const keyPath = join(fixturesDir, "repo-key.json");
const distDir = join(fixturesDir, "dist");

if (!existsSync(keyPath)) {
  console.error("No fixtures/repo-key.json found — run `node scripts/gen-keys.mjs` first.");
  process.exit(1);
}
const { publicKey, privateKey } = JSON.parse(readFileSync(keyPath, "utf8"));

const version = Number(process.argv[2] ?? 1);

const crl = buildCrl(privateKey, {
  repoId: "com.example.journalist-kit",
  kid: keyId(publicKey),
  version,
  // Sample: whole-app revocation of "courier-mirror" (the fixture with a
  // deliberately mismatched checksum in build-index.mjs's sampleApps()), plus
  // a single-version revocation of a hypothetical old build of "vault-mirror".
  revokedIds: ["courier-mirror"],
  revokedVersions: ["vault-mirror@13"],
});

mkdirSync(distDir, { recursive: true });
const bytes = Buffer.from(JSON.stringify(crl, null, 2) + "\n", "utf8");
writeFileSync(join(distDir, "revocations.json"), bytes);

console.log("Wrote a signed Depot CRL to fixtures/dist/revocations.json:");
console.log("  version:        ", crl.payload.version);
console.log("  revoked_ids:    ", crl.payload.revoked_ids);
console.log("  revoked_versions:", crl.payload.revoked_versions);
console.log("  next_update:    ", new Date(crl.payload.next_update * 1000).toISOString());
console.log("  max_stale_secs: ", crl.payload.max_stale_secs);
